from abc import ABC, abstractmethod
from dataclasses import dataclass
import threading
from typing import Dict, Optional, Tuple

@dataclass
class TokenBucketState:
    tokens: float
    last_updated: float

class BaseStorage(ABC):
    @abstractmethod
    def get_and_update(
        self,
        key: str,
        capacity: float,
        refill_rate: float,
        cost: float,
        current_time: float,
    ) -> Tuple[bool, float, float]:
        pass

    @abstractmethod
    def reset(self, key: Optional[str] = None) -> None:
        pass

class MemoryStorage(BaseStorage):
    def __init__(self) -> None:
        self._states: Dict[str, TokenBucketState] = {}
        self._lock = threading.Lock()

    def get_and_update(
        self,
        key: str,
        capacity: float,
        refill_rate: float,
        cost: float,
        current_time: float,
    ) -> Tuple[bool, float, float]:
        with self._lock:
            state = self._states.get(key)
            if state is None:
                current_tokens = float(capacity)
                last_updated = current_time
            else:
                elapsed = max(0.0, current_time - state.last_updated)
                current_tokens = min(float(capacity), state.tokens + (elapsed * refill_rate))
                last_updated = current_time

            if current_tokens >= cost:
                new_tokens = current_tokens - cost
                self._states[key] = TokenBucketState(new_tokens, last_updated)
                return True, new_tokens, 0.0
            else:
                self._states[key] = TokenBucketState(current_tokens, last_updated)
                retry_after = max(0.0, (cost - current_tokens) / refill_rate)
                return False, current_tokens, retry_after

    def reset(self, key: Optional[str] = None) -> None:
        with self._lock:
            if key:
                self._states.pop(key, None)
            else:
                self._states.clear()
